package com.rpsbattle.tournament;
import com.rpsbattle.account.domain.*;import com.rpsbattle.account.repository.UserRepository;import com.rpsbattle.auth.AuthService;import com.rpsbattle.tournament.domain.*;import com.rpsbattle.tournament.persistence.TournamentRepository;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class CheckInFlowTest {
 @Autowired OwnedTournamentService owned;@Autowired UserRepository users;@Autowired TournamentRepository repository;
 org.springframework.security.core.Authentication account(){var now=Instant.now();String name="checkin_"+UUID.randomUUID().toString().substring(0,8);return AuthService.sessionAuthentication(users.save(new User(UserId.random(),name,name+"@example.invalid","fixture",name,UserRole.USER,AccountStatus.ACTIVE,now,now,null,0)));}
 @Test void checkInIsSelfOnlyIdempotentAndServerClosesMissedDeadline(){var owner=account();var a=account();var b=account();var t=owned.create(owner,"Timed check in",TournamentFormat.ROUND_ROBIN,"PUBLIC",true,4,null,null,ParticipantPolicy.HUMAN_ONLY);var deadline=Instant.now().plusSeconds(120);owned.configureTiming(owner,t.id,t.revision,new TournamentTiming(null,deadline,null));owned.openRegistration(owner,t.id);owned.registerHuman(a,t.id,true);owned.registerHuman(b,t.id,true);for(var r:List.copyOf(t.registrations))owned.review(owner,t.id,r.id().toString(),true);owned.closeRegistration(owner,t.id);var mine=t.registrations.getFirst();
  assertThatThrownBy(()->owned.checkIn(b,t.id,mine.id().toString())).hasMessage("TOURNAMENT_FORBIDDEN");owned.checkIn(a,t.id,mine.id().toString());owned.checkIn(a,t.id,mine.id().toString());assertThat(t.registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.CHECKED_IN);
  var stored=repository.all().stream().filter(r->r.id().toString().equals(t.id)).findFirst().orElseThrow();assertThat(stored.details().timing().checkInDeadline()).isEqualTo(deadline);
  try{owned.clock(Clock.fixed(deadline.plusSeconds(1),ZoneOffset.UTC));assertThatThrownBy(()->owned.checkIn(b,t.id,null)).hasMessage("CHECK_IN_NOT_OPEN");owned.expireCheckIns();assertThat(t.status).isEqualTo(TournamentStatus.CANCELLED);assertThat(t.registrations.get(1).status()).isEqualTo(TournamentRegistration.Status.NOT_CHECKED_IN);assertThat(t.operations.audit().getLast().reason()).isEqualTo("CHECK_IN_DEADLINE");}finally{owned.clock(Clock.systemUTC());}
 }
 @Test void registrationDeadlineRejectsLateHumanWithoutTrustingClientTime(){var owner=account();var t=owned.create(owner,"Closed deadline",TournamentFormat.ROUND_ROBIN,"PUBLIC",false,4,null,null,ParticipantPolicy.HUMAN_ONLY);var deadline=Instant.now().plusSeconds(60);owned.configureTiming(owner,t.id,t.revision,new TournamentTiming(deadline,null,null));owned.openRegistration(owner,t.id);try{owned.clock(Clock.fixed(deadline,ZoneOffset.UTC));assertThatThrownBy(()->owned.registerHuman(owner,t.id,true)).hasMessage("REGISTRATION_CLOSED");assertThat(t.registrations).isEmpty();}finally{owned.clock(Clock.systemUTC());}}
}
